UPDATE
	coupon_birth
SET
	shop_num=#{shopNum}
	,using_date=#{usingDate}
	,w_memo=#{wMemo}
WHERE
	coupon_cd = #{couponCd};

    	UPDATE
			sale_off
		SET
			coupon_birth=#{couponBirth}
		WHERE
			sale_id = #{saleId};

mapper.select:
SELECT cstmr_id ,C.cstmr_cd ,C.cstmr_name ,C.telephone ,C.cellphone ,C.addr ,C.birth_day ,(select coupon_cd from coupon_birth where cstmr_cd = C.cstmr_cd order by coupon_cd desc limit 1) as coupon_cd ,(select shop_num from coupon_birth where cstmr_cd = C.cstmr_cd order by coupon_cd desc limit 1) as shop_num ,(select shop_name from shop where shop_id = (select shop_num from coupon_birth where cstmr_cd = C.cstmr_cd order by coupon_cd desc limit 1)) as shop_name ,(select using_date from coupon_birth where cstmr_cd = C.cstmr_cd order by coupon_cd desc limit 1) as using_date ,(select w_memo from coupon_birth where cstmr_cd = C.cstmr_cd order by coupon_cd desc limit 1) as coupon_memo FROM cstmr C
C.cstmr_name = #{cstmrName}
and (right(C.cellphone,4) = #{digit4} OR right(C.telephone,4) = #{digit4})
or cstmr_cd = #{cstmrCd}
order by C.cstmr_cd;
